/**
 * Test flows for Created trigger
 *
 * Flow 1: Tests record creation trigger with all input parameters and outputs
 * Flow 2: Tests DEF0777644 - Demonstrates that only mandatory fields are required
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow 1: Created trigger with all parameters
export const testCreatedTrigger = Flow(
    {
        $id: Now.ID['test_created_trigger_flow'],
        name: 'Test Created Trigger',
        description: 'Tests the Created trigger with all parameters',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_created_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_on_extended: 'false',
            run_when_setting: 'both',
            run_flow_in: 'background',
            run_when_user_setting: 'any',
            run_when_user_list: [],
        }
    ),
    (_params) => {
        // Log all trigger outputs
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['test_created_trigger_log'],
            },
            {
                log_level: 'info',
                log_message: `Created Trigger - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')} Assignment Group : ${wfa.dataPill(_params.trigger.current.assignment_group, 'reference')} Assignment Group Description : ${wfa.dataPill(_params.trigger.current.assignment_group.description, 'string')}`,
            }
        )
    }
)

// Flow 2: Created trigger with mandatory fields only (DEF0777644)
export const testCreatedTriggerMandatoryOnly = Flow(
    {
        $id: Now.ID['test_created_trigger_mandatory_only_flow'],
        name: 'Test Created Trigger - Mandatory Only',
        description: 'DEF0777644: Tests Created trigger with only mandatory table input',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_created_trigger_mandatory_only'] },
        {
            table: 'incident',
        }
    ),
    (_params) => {
        // Log trigger execution
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_created_trigger_mandatory_only_log'] },
            {
                log_level: 'info',
                log_message: `Created Trigger (Mandatory Only) - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}, Assignment Group: ${wfa.dataPill(_params.trigger.current.assignment_group, 'reference')}, Assignment Group Description: ${wfa.dataPill(_params.trigger.current.assignment_group.description, 'string')}`,
            }
        )
    }
)

// Flow 3: Created trigger with all non default parameters
export const testCreatedTriggerWithNonDefaultParams = Flow(
    {
        $id: Now.ID['test_created_trigger_non_default_flow'],
        name: 'Test Created Trigger - Non Default',
        description: 'Tests the Created trigger with all non-default parameters',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_created_trigger_non_default'] },
        {
            table: 'incident',
            condition: 'active=true^short_descriptionSTARTSWITHOutage',
            run_on_extended: 'true',
            run_flow_in: 'foreground',
            run_when_user_list: ['62826bf03710200044e0bfc8bcbe5df1'],
            run_when_setting: 'non_interactive',
            run_when_user_setting: 'one_of',
        }
    ),
    (_params) => {
        // Log all trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_created_trigger_non_default_log'] },
            {
                log_level: 'info',
                log_message: `Created Trigger - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}, Assignment Group: ${wfa.dataPill(_params.trigger.current.assignment_group, 'reference')}, Assignment Group Description: ${wfa.dataPill(_params.trigger.current.assignment_group.description, 'string')}`,
            }
        )
    }
)
